True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    for r, row in enumerate(grid):
        if all(v == row[0] for v in row):
            for c in range(w):
                out[r][c] = 2
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out
